An example of opening a WAV file and looping through to get each audio sample (assuming the audio file contains 16-bit audio): WAVFileaudioFile("someAudioFile.wav");
AudioFileResultTyperesult=audioFile.open(AUDIO_FILE_READ);
if(result)
{
size_tnumSamples=audioFile.numSamples();
for(size_ti=0;(i<numSamples)&&result;++i)
{
int16_taudioSample=0;
result=audioFile.getNextSample(audioSample);
}
}
else
{
cerr<<"Error(s)gettingaudiosamples:"<<endl;
result.outputErrors(cerr);
}
audioFile.close();
